namespace ghidra.app.util.viewer.format.actions;

using ghidra.app.util;
using ghidra.app.util.viewer.field;
using ghidra.app.util.viewer.format;
using ghidra.app.util.viewer.format;
using ghidra.util;
using docking;
using docking.action;
using docking.action;

/**
 * Action for enabling disabled fields
 */
public class EnableFieldAction : DockingAction {
	private FieldHeaderLocation loc;
	private FieldHeader panel;

    /**
     * Constructor
  	 * @param owner the action owner
     */
    public EnableFieldAction(string owner, FieldHeader panel) : base("Enable Field", owner, false)
    {
        this.panel = panel;

        setPopupMenuData( new MenuData( new string[] {"Enable Field"},null,"field" ) );
        setEnabled(true);
		setHelpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Enable Field"));
	}

    /* @Override */
    public bool isEnabledForContext(ActionContext context) {
    	object contextObject = context.getContextObject();
		if (contextObject is FieldHeaderLocation) {
			loc = (FieldHeaderLocation)contextObject;
			FieldFactory ff = loc.getFieldFactory();
			return ff != null && !ff.isEnabled(); 
		}
		return false;
	}

    /* @Override */
    public void actionPerformed(ActionContext context) {
		FieldFactory factory = loc.getFieldFactory();
		panel.setTabLock( true );
        factory.setEnabled(true);
	}

}

